:root {
  /* ==========================================
     我方气泡 (轻质冷灰色、无边框、缩小、方圆)
  ========================================== */
  --bubble-me-bg: #E2E2E5;               /* 变更为高级冷灰色 */
  --bubble-me-bg-gradient: initial;
  --bubble-me-color: #2C2C2E;            /* 文字适配为曜石黑 */
  --bubble-me-border: none;
  --bubble-me-shadow: 0 1px 3px rgba(0, 0, 0, 0.02);
  --bubble-me-link-color: #707074;       

  /* 1. 缩小整体与高度 */
  --bubble-me-font-size: 14px;
  --bubble-me-line-height: 1.35;
  --bubble-me-padding: 7px 12px;

  /* 2. 方圆形外观 */
  --bubble-me-radius: 12px;
  --bubble-me-radius-first: 12px 12px 4px 12px;
  --bubble-me-radius-mid: 12px 4px 4px 12px;
  --bubble-me-radius-last: 12px 4px 12px 12px;

  /* ==========================================
     对方气泡 (白色、特定边框、缩小、方圆)
  ========================================== */
  --bubble-them-bg: #FFFFFF;
  --bubble-them-bg-gradient: initial;
  --bubble-them-color: #2C2C2E;          
  --bubble-them-border: 1px solid #E5E5EA; /* 边框变冷灰色 */
  --bubble-them-shadow: 0 1px 2px rgba(0, 0, 0, 0.03);
  --bubble-them-link-color: #707074;

  /* 1. 缩小整体与高度 */
  --bubble-them-font-size: 14px;
  --bubble-them-line-height: 1.35;
  --bubble-them-padding: 7px 12px;

  /* 2. 方圆形外观 */
  --bubble-them-radius: 12px;
  --bubble-them-radius-first: 12px 12px 12px 4px;
  --bubble-them-radius-mid: 4px 12px 12px 4px;
  --bubble-them-radius-last: 4px 12px 12px 12px;

  /* ==========================================
     相关组件同步缩小与适配
  ========================================== */
  --translation-btn-color: #707074;
  --translation-text-color: #555558;
  --translation-bg: rgba(242, 242, 247, 0.5);
  --translation-size: 12.5px;
  --translation-padding: 6px 10px;

  --voice-me-color: #2C2C2E;             /* 我方语音图标 */
  --voice-me-bar-active: #2C2C2E;        /* 我方波形 */
  --voice-me-bar-inactive: rgba(0, 0, 0, 0.12);
  --voice-them-color: #2C2C2E;           /* 对方语音图标 */
  --voice-them-bar-active: #2C2C2E;      /* 对方波形 */
  --voice-them-bar-inactive: #E5E5EA;

  --plain-avatar-radius: 12px;
  --avatar-radius: 12px;
}

/* ==========================================
   一、头像显示逻辑 (隐藏时保留占位，气泡完美对齐)
========================================== */
.msg-avatar-me-container {
  visibility: hidden !important;
}
.msg-avatar-me-container.is-last,
.msg-avatar-me-container.is-single {
  visibility: visible !important;
}

.msg-avatar-them-container {
  visibility: hidden !important;
}
.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single {
  visibility: visible !important;
}

/* ==========================================
   二、【我方头像】对齐与上下左右微调
========================================== */
.msg-avatar-me-container {
  align-self: flex-end !important;
  position: relative !important;
  left: -30px !important;
  top: 40px !important;
  margin-left: 10px !important; 
  overflow: visible !important;          
}

/* ==========================================
   三、【对方头像】对齐与上下左右微调
========================================== */
.msg-avatar-them-container {
  position: relative !important;
  left: 30px !important;
  top: -40px !important;
  margin-right: 10px !important;
  overflow: visible !important;          
}

/* ==========================================
   四、双方消息间距调整 (换人发言时较宽)
========================================= */
.msg-bubble-wrapper.is-last,
.msg-bubble-wrapper.is-single {
  margin-bottom: 30px !important; 
}

/* ==========================================
   五、头像：方圆形 + 白色边框 + 可旋转超大双层底框 (双层独立阴影)
========================================== */
.msg-avatar-me-inner,
.msg-avatar-them-inner,
.msg-avatar-custom {
  border-radius: 12px !important;
  border: 2px solid #FFFFFF !important;    
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.13) !important; 
  box-sizing: border-box !important;
  position: relative !important;
  z-index: 3 !important;                   
}

.msg-avatar-me-container::before,
.msg-avatar-them-container::before {
  content: "";
  position: absolute;
  top: -1px !important;
  left: -1px !important;
  right: -1px !important;
  bottom: -1px !important;

  border-radius: 14px !important;          
  background: #FFFFFF !important;          
  border: 1px solid #E5E5E5 !important;    
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.10) !important; 

  z-index: 1 !important;                   
  pointer-events: none !important;
  transform: translateY(-3px) translateX(-3px) rotate(-10deg) !important;     
}

/* ==========================================
   六、对方消息左侧：贯穿竖线与圆点 (羽灰色极简)
========================================== */
.msg-avatar-them-container::after,
.msg-bubble-wrapper.msg-them::after {
  display: none !important;
  background: none !important;
}

.msg-bubble-wrapper.msg-them::before {
  content: "" !important;
  position: absolute !important;
  z-index: 10 !important;
  pointer-events: none !important;
  width: 10px !important;            
  transform: translateX(-50%) !important; 
  left: 20px !important; 
}

.msg-bubble-wrapper.msg-them.is-first::before {
  top: -15px !important;             
  bottom: -35px !important; 
  background: linear-gradient(#D1D1D6, #D1D1D6) no-repeat center top !important; /* 线条变羽灰 */
  background-size: 2px 100% !important;
}

.msg-bubble-wrapper.msg-them.is-mid::before {
  top: -20px !important; 
  bottom: -35px !important; 
  background: linear-gradient(#D1D1D6, #D1D1D6) no-repeat center top !important;
  background-size: 2px 100% !important;
}

.msg-bubble-wrapper.msg-them.is-last::before {
  top: -20px !important; 
  bottom: 10px !important;           
  background: 
    radial-gradient(circle, #D1D1D6 4px, transparent 4.5px) no-repeat center bottom,
    linear-gradient(#D1D1D6, #D1D1D6) no-repeat center top !important;
  background-size: 8px 8px, 2px calc(100% - 4px) !important;
}

.msg-bubble-wrapper.msg-them.is-single::before {
  top: -15px !important;             
  bottom: 10px !important; 
  background: 
    radial-gradient(circle, #D1D1D6 4px, transparent 4.5px) no-repeat center bottom,
    linear-gradient(#D1D1D6, #D1D1D6) no-repeat center top !important;
  background-size: 8px 8px, 2px calc(100% - 4px) !important;
}

/* ==========================================
   七、我方消息右侧：贯穿竖线与顶部圆点 (羽灰色极简)
========================================= */
.msg-avatar-me-container::after,
.msg-bubble-wrapper.msg-me::after {
  display: none !important;
  background: none !important;
}

.msg-bubble-wrapper.msg-me::before {
  content: "" !important;
  position: absolute !important;
  z-index: 10 !important;
  pointer-events: none !important;
  width: 10px !important;            
  transform: translateX(50%) !important;  
  right: 20px !important; 
}

.msg-bubble-wrapper.msg-me.is-first::before {
  top: 10px !important;             
  bottom: -50px !important;          
  background: 
    radial-gradient(circle, #D1D1D6 4px, transparent 4.5px) no-repeat center top,
    linear-gradient(#D1D1D6, #D1D1D6) no-repeat center bottom !important;
  background-size: 8px 8px, 2px calc(100% - 4px) !important;
  background-position: center top, center bottom !important; 
}

.msg-bubble-wrapper.msg-me.is-mid::before {
  top: -20px !important; 
  bottom: -35px !important; 
  background: linear-gradient(#D1D1D6, #D1D1D6) no-repeat center top !important;
  background-size: 2px 100% !important;
}

.msg-bubble-wrapper.msg-me.is-last::before {
  top: -20px !important; 
  bottom: 30px !important;           
  background: linear-gradient(#D1D1D6, #D1D1D6) no-repeat center top !important;
  background-size: 2px 100% !important;
}

.msg-bubble-wrapper.msg-me.is-single::before {
  top: 5px !important;             
  bottom: -20px !important;           
  background: 
    radial-gradient(circle, #D1D1D6 4px, transparent 4.5px) no-repeat center top,
    linear-gradient(#D1D1D6, #D1D1D6) no-repeat center bottom !important;
  background-size: 8px 8px, 2px calc(100% - 4px) !important;
  background-position: center top, center bottom !important; 
}

/* ==========================================
   八、双方头像旁侧标签 (冷灰色字)
========================================== */
.msg-avatar-me-inner,
.msg-avatar-them-inner {
  overflow: hidden !important;           
