/* ---------- 对方气泡：白色方圆（无边框）缩小版 + 左侧中间装饰 ---------- */
:root {
  /* 对方气泡颜色 */
  --bubble-them-bg: #ffffff;
  --bubble-them-color: #1f2d3d;

  /* 对方气泡圆角（缩小版） */
