  --bubble-them-radius-first: 10px 10px 10px 5px;
  --bubble-them-radius-mid: 5px 10px 10px 5px;
  --bubble-them-radius-last: 5px 10px 10px 10px;

  /* 缩小内边距（左侧留出空间给装饰图） */
  --bubble-them-padding: 6px 10px 6px 6px;

  /* 缩小字号 */
  --bubble-them-font-size: 13px;

  /* 无边框 */
  --bubble-them-border: none;

  /* 轻微阴影 */
  --bubble-them-shadow: 0 1px 2px rgba(0, 0, 0, 0.04);

  /* 对方气泡内链接颜色 */
