.bubble-me-custom.first {
  border-radius: var(--bubble-me-radius-first, 10px 10px 5px 10px) !important;
}
.bubble-me-custom.mid {
  border-radius: var(--bubble-me-radius-mid, 10px 5px 5px 10px) !important;
}
.bubble-me-custom.last {
  border-radius: var(--bubble-me-radius-last, 10px 5px 10px 10px) !important;
}
.bubble-me-custom.single {
