  min-width: 36px !important;      /* 防止被压缩 */
  pointer-events: auto !important; /* 确保可以点击 */
  cursor: pointer !important;      /* 鼠标指针样式 */
}

/* 同时隐藏语音按钮内的任何 SVG 图标 */
.input-btn-mic svg {
  display: none !important;
}

